pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract directly (balance that withdrawAll must pay out)
        vm.deal(address(c), amount);
        // ensure the owner (this test contract) has room to receive the payout
        vm.deal(address(this), 2 * amount);

        uint256 ownerBefore = address(this).balance;

        // owner drives c through withdrawAll (gas price is 0 in Foundry tests)
        c.withdrawAll();

        // General rule: after withdrawAll, the owner's balance has increased by
        // exactly the balance the contract held before the call.
        assertTrue(address(this).balance == ownerBefore + amount);
    }
}

