pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        // owner (this test contract) funds the contract via its fallback
        vm.deal(address(this), amount);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "fund failed");

        uint256 before = address(c).balance;
        require(before == amount, "balance mismatch");

        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: it is impossible for withdrawAll to succeed AND leave the
        // contract holding the entire pre-call balance untouched.
        assertTrue(!(ok && address(c).balance == before));
    }
}

