pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 zeroCalls) public {
        vm.assume(depositAmount <= type(uint128).max);
        zeroCalls = bound(zeroCalls, 0, 3);

        address depositor = makeAddr("depositor");
        vm.deal(depositor, depositAmount);

        // zero-value fallback calls: raise depositsCount without adding balance
        for (uint256 i = 0; i < zeroCalls; ++i) {
            vm.prank(depositor);
            (bool s, ) = address(c).call{value: 0}("");
            assertTrue(s);
        }

        // funded deposit
        if (depositAmount > 0) {
            vm.prank(depositor);
            (bool s2, ) = address(c).call{value: depositAmount}("");
            assertTrue(s2);
        }

        // trigger: zeroCalls zero-value calls give depositsCount > balance when depositAmount == 0 and zeroCalls >= 1
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // owner's withdrawAll must always succeed and drain the balance
        assertTrue(ok && address(c).balance == 0);
    }
}

