pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 n) public {
        // Admissible domain: at least one deposit recorded via zero-value fallback hits.
        n = bound(n, 1, 500);

        // Record n deposits without ever funding the contract (zero-value fallback calls).
        for (uint256 i = 0; i < n; i++) {
            (bool okDep, ) = address(c).call("");
            assertTrue(okDep);
        }
        // depositsCount == n while contract balance is still 0.
        assertEq(c.depositsCount(), n);
        assertEq(address(c).balance, 0);

        // Owner withdraws everything. Reference transfers address(this).balance == 0,
        // which always succeeds. The mutant transfers depositsCount (n > 0) while the
        // balance is 0, so its transfer reverts.
        vm.prank(c.owner());
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

