pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v) public {
        v = bound(v, 2, 1e30);
        // fund c through its payable fallback: balance becomes v, depositsCount becomes 1
        vm.deal(address(this), v);
        (bool okF, ) = address(c).call{value: v}("");
        assertTrue(okF);
        assertTrue(address(c).balance == v);

        // owner (this contract, the deployer) withdraws everything
        uint256 before = address(this).balance;
        c.withdrawAll();

        // RULE: withdrawAll transfers exactly address(c).balance, so the owner's
        // balance increases by exactly v. The mutant transfers depositsCount (=1),
        // so the owner only receives 1 wei (v >= 2).
        assertTrue(address(this).balance == before + v);
    }
}

