pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    receive() external payable {}

    function testFuzz_property(uint256 n, uint256 v, uint256 e) public {
        n = bound(n, 1, 50);
        v = bound(v, 0, 1e18);
        e = bound(e, 0, 1e18);

        // directly credit the contract without incrementing depositsCount
        vm.deal(address(c), e);

        // n fallback deposits of value v each
        address depositor = address(0xa11ce);
        vm.deal(depositor, n * v);
        vm.startPrank(depositor);
        for (uint256 i = 0; i < n; i++) {
            (bool s, ) = address(c).call{value: v}("");
            require(s);
        }
        vm.stopPrank();

        // rule: the owner can always withdrawAll — the reference transfers
        // exactly address(this).balance, which never exceeds the balance,
        // so it never reverts regardless of depositsCount vs balance.
        vm.prank(c.owner());
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

