import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v, uint256 w, uint256 r) public {
        // keep the domain wide but admissible: v, w are two withdraws, r > 0 is leftover
        v = bound(v, 0, 1 ether);
        w = bound(w, 0, 1 ether);
        r = bound(r, 1, 1 ether);
        uint256 total = v + w + r;
        vm.deal(address(c), total);

        bool ok1;
        bool ok2;
        try c.withdraw(v) { ok1 = true; } catch { ok1 = false; }
        try c.withdraw(w) { ok2 = true; } catch { ok2 = false; }

        // Rule: two withdraws of v then w succeed and leave exactly total - v - w in the contract.
        assertTrue(ok1 && ok2 && address(c).balance == total - v - w);
    }
}

