import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    receive() external payable {}

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        // fund via the contract's payable fallback: any deposit is admissible
        deposit = bound(deposit, 1, 100 ether);
        // any withdrawal amount up to the funded balance is admissible (wide domain)
        amount = bound(amount, 1, deposit);

        vm.deal(address(this), deposit);
        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent, "fallback deposit failed");

        // owner (the test contract, = deployer) withdraws exactly `amount`
        c.withdraw(amount);

        // GENERAL RULE: after withdrawing `amount` of the `deposit` held,
        // the contract retains exactly deposit - amount, for every admissible
        // (deposit, amount) pair. The mutant always drains the full balance,
        // leaving 0 instead of deposit - amount whenever amount < deposit.
        assertTrue(address(c).balance == deposit - amount);
    }
}

