contract InvMutTest {
	C private c;

	constructor(C _c) {
		c = _c;
	}

	function testNonOwnerCannotWithdraw() external {
		// The test contract is (in general) not the owner of c, since c's owner
		// is whoever deployed it. Owner-protected entry points must therefore
		// revert for the test contract as caller.

		bool revertedAll = false;
		try c.withdrawAll() {
			revertedAll = false;
		} catch {
			revertedAll = true;
		}

		bool revertedPart = false;
		try c.withdraw(1) {
			revertedPart = false;
		} catch {
			revertedPart = true;
		}

		bool revertedSend = false;
		try c.sendMoney(address(0x1), 1, "") {
			revertedSend = false;
		} catch {
			revertedSend = true;
		}

		// General rule: every owner-only entry point reverts for a non-owner caller.
		assert(revertedAll && revertedPart && revertedSend);
	}

	receive() external payable {}
	fallback() external payable {}
}

