    function run(address target, uint value, bytes memory data) public payable {
        // fund c through its payable fallback so the sub-call can fail due to insufficient balance
        uint fund = 1 wei;
        require(address(this).balance >= fund);
        address(c).call{value: fund}("");
        require(value > address(c).balance, "precondition");
        bool reverted;
        try c.sendMoney(target, value, data) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address target, bytes memory data) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(data.length > 0, "need non-empty calldata");
        require(target == address(this), "target must be this reverting-fallback contract");
        bool reverted;
        c.sendMoney(target, amount, data);
        reverted = false;
        // unreachable on P; kept for shape
        assert(reverted == false || data.length == 0);
    }
    receive() external payable {
        // empty calldata: succeeds (mutant path completes)
    }
    fallback() external payable {
        // non-empty calldata: reverts (original forwards _data here)
        revert("fallback reverts");
    }
}
